api.look('noir');
const cx = api.w/2, cy = 340;
const k = api.seg(t, 0, 2.5);
const pts = api.pts.circle(40, 0, 0, 70);
const wob = pts.map((p,i)=>({x:p.x+(api.noise(i*0.7+t*3)-0.5)*40*k, y:p.y+(api.noise(i*0.7+50+t*3)-0.5)*40*k}));
api.blob(api.move(wob, cx, cy, 1+k*0.4, 0), {c:'accent', w:3, fill:'accent', a:0.3});
api.circle(cx, cy, 12, {c:'fg', fill:'fg'});
api.say('A small worry starts', 0.3, 3.2);

api.look('noir');
const cx = api.w/2, cy = 340;
const k = api.seg(t, 0, 5);
const e = api.ease(k);
api.cam(0, 0, 1 + e*0.35, api.noise(t*2)*0.04*e);
for (let r = 0; r < 7; r++) {
  const rk = api.stag(t, r, {gap:0.5, dur:1.2, from:0});
  const R = 60 + r*34 - e*r*10;
  const pts = api.pts.circle(36, 0, 0, R).map((p,i)=>({
    x:p.x+(api.noise(i*0.9+r*9+t*(2+e*6))-0.5)*(10+e*40),
    y:p.y+(api.noise(i*0.9+r*9+80+t*(2+e*6))-0.5)*(10+e*40)}));
  api.blob(api.move(pts, cx, cy, 1, 0), {c: r%2?'accent':'warn', w:2.5, a:0.9*rk, fill:'none'});
}
api.swarm(90, t, {mode:'suck', cx, cy, rx:170, ry:200, c:'accent', k:e});
api.counter(Math.round(72 + e*88), cx, 640, {size:56, suf:' bpm', k:1});
api.shake(t, 5*e);
api.cam0();
api.say('Thoughts pile on, faster', 0.4, 5.5);

api.look('noir');
const cx = api.w/2, cy = 340;
const k = api.seg(t, 0, 2.8);
const hold = api.seg(t, 2.8, 4.2);
api.cam(0, 0, 1.35 + k*0.15, api.noise(t*8)*0.05);
for (let r = 0; r < 8; r++) {
  const R = 50 + r*30;
  const pts = api.pts.circle(36, 0, 0, R).map((p,i)=>({
    x:p.x+(api.noise(i*1.3+r*9+t*9)-0.5)*60,
    y:p.y+(api.noise(i*1.3+r*9+80+t*9)-0.5)*60}));
  api.blob(api.move(pts, cx, cy, 1, 0), {c:'bad', w:3, glow:true, fill:'none'});
}
api.glow(cx, cy, 80+api.pulse(t,4)*30, {c:'bad'});
api.shake(t, 9);
api.cam0();
api.text('too much', cx, 640, {size:40, c:'bad', align:'center', weight:700, k:api.seg(t,1,2)});
api.say('It feels like too much', 0.3, 4.5);

api.look('noir');
const cx = api.w/2, cy = 340;
const k = api.seg(t, 0, 5.5), e = api.ease(k);
const bre = 0.5 + 0.5*Math.sin(t*1.6 - 1.57);
for (let r = 0; r < 8; r++) {
  const R = 50 + r*30 + (1-e)*10;
  const amp = (1-e)*50 + 2;
  const pts = api.pts.circle(36, 0, 0, R).map((p,i)=>({
    x:p.x+(api.noise(i*1.3+r*9+t*2)-0.5)*amp,
    y:p.y+(api.noise(i*1.3+r*9+80+t*2)-0.5)*amp}));
  api.blob(api.move(pts, cx, cy, 1+bre*0.12*e, 0), {c:api.lerp(0,1,e)>0.5?'a2':'accent', w:2.5, a:0.9-r*0.07, fill:'none'});
}
api.glow(cx, cy, 90+bre*40*e, {c:'a2'});
api.arc(cx, 640, 40, -1.57, -1.57+6.28*((t/6)%1), {c:'a2', w:4});
api.say('One slow breath in', 0.3, 3);
api.say('And out', 3.2, 5.8);

api.look('noir');
const cx = api.w/2, cy = 340;
const e = api.ease(api.seg(t, 0, 4));
for (let r = 0; r < 8; r++) {
  const R = 50 + r*30 + e*r*14;
  const pts = api.pts.circle(36, 0, 0, R).map((p,i)=>({
    x:p.x+(api.noise(i*0.8+r*9+t*0.8)-0.5)*6,
    y:p.y+(api.noise(i*0.8+r*9+80+t*0.8)-0.5)*6}));
  api.blob(api.move(pts, cx, cy, 1, 0), {c:'a2', w:2, a:(1-e)*(0.9-r*0.08), fill:'none'});
}
api.swarm(80, t, {mode:'rise', cx, cy:cy+60, rx:160, ry:200, c:'a2', glow:true, k:e});
api.stars(40, t);
api.glow(cx, cy, 70+e*80, {c:'good'});
api.cam(0, 0, 1+api.seg(t,2,7)*0.1, 0);
api.cam0();
api.text('softer', cx, 640, {size:40, c:'good', align:'center', weight:700, k:api.seg(t,2.5,3.5)});
api.say('Then it lets go', 0.4, 3.5);
api.say('Space opens up', 4, 6.8);
